python3 -c 'import os, sys, json, urllib.request; snap="${answer1}".strip(); snap = snap if os.path.exists(snap) else (f"snapshots/users_snapshot_{snap}.json" if os.path.exists(f"snapshots/users_snapshot_{snap}.json") else snap);
if not os.path.exists(snap): print(json.dumps({"error": f"Snapshot {snap} not found", "status": "failed"})); sys.exit(0)
snap_users = json.load(open(snap)); okta_url = os.getenv("OKTA_URL", "").rstrip("/"); token = os.getenv("OKTA_API_TOKEN", ""); headers = {"Accept": "application/json", "Content-Type": "application/json", "Authorization": f"SSWS {token}"}
req = urllib.request.Request(f"{okta_url}/api/v1/users?limit=200", headers=headers); cur_users = json.loads(urllib.request.urlopen(req).read().decode()) if token else []
cur_by_login = {u.get("profile",{}).get("login","").lower(): u for u in cur_users}
created, updated, skipped, errors = [], [], [], []
for u in snap_users:
    sp = u.get("profile", {}); login = sp.get("login", sp.get("email","")).lower()
    if not login: continue
    if login not in cur_by_login:
        p = json.dumps({"profile": sp, "credentials": {"password": {"value": "TempRestore123!"}}}).encode()
        r = urllib.request.Request(f"{okta_url}/api/v1/users?activate=true", data=p, headers=headers, method="POST")
        try: urllib.request.urlopen(r); created.append(login)
        except Exception as e: errors.append(f"Create {login}: {e}")
    else:
        cur_p = cur_by_login[login].get("profile", {}); cur_id = cur_by_login[login].get("id")
        diff = {k: v for k, v in sp.items() if v is not None and cur_p.get(k) != v}
        if diff:
            p = json.dumps({"profile": diff}).encode()
            r = urllib.request.Request(f"{okta_url}/api/v1/users/{cur_id}", data=p, headers=headers, method="POST")
            try: urllib.request.urlopen(r); updated.append(login)
            except Exception as e: errors.append(f"Update {login}: {e}")
        else: skipped.append(login)
print(json.dumps({"status": "completed", "snapshot": snap, "recreated_deleted": len(created), "updated_modified": len(updated), "untouched_skipped": len(skipped), "errors": errors}))'
